application/json.example:
// CASE (which id field is required depends on target_type):
// - target_type=all_users -> sends to every active student+teacher+parent, no *_ids needed.
// - target_type=all_students / all_teachers / all_parents -> sends to every active user of that ONE role, no *_ids needed.
// - target_type=students -> student_ids[] REQUIRED (or generic ids[] as fallback).
// - target_type=teachers -> teacher_ids[] REQUIRED (or ids[]).
// - target_type=parents -> parent_ids[] REQUIRED (or ids[]).
// channels[] is independent of target_type: push and/or email, applies the same way regardless of who's targeted.

{
  "target_type": "all_users",
  "title": "string",
  "body": "string",
  "message": "string",
  "channels": [
    "push"
  ],
  "data": {},
  "student_ids": [
    1
  ],
  "teacher_ids": [
    1
  ],
  "parent_ids": [
    1
  ],
  "ids": [
    1
  ]
}

// CASE (course_id/unit_id set vs both null):
// - course_id and/or unit_id SET -> this is a course/unit-bundled book: price is FORCED to 0.00 server-side no matter what you send, and students can ONLY access it via their course/unit subscription (POST /student/books/subscribe will actively REJECT a standalone purchase attempt on it).
// - course_id and unit_id BOTH null -> standalone book: submitted price is honored as-is, and students buy it individually via /student/books/subscribe.
// CASE (allow_download): 1 (default) = student gets a direct downloadable link; 0 = file_path/link are hidden from the student response entirely and they must use GET /student/books/stream instead.

{
  "subject_id": 1,
  "course_id": 1,
  "unit_id": 1,
  "file_type": "string",
  "extension": "string",
  "link": "string",
  "file_path": "string",
  "cover_image": "string",
  "price": 1,
  "allow_download": 1,
  "is_active": 0
}

// CASE (validation path depends on which of course_id/subject_id is sent):
// - course_id set -> validated as a COURSE session: rejected if the teacher isn't assigned to that course, or if another teacher already owns it.
// - course_id empty + subject_id set -> validated as a SUBJECT session: rejected if the teacher isn't assigned to that subject for the given academic_year_id (grade).
// CASE (academic_year_id): null/omitted = session is open to ALL grades; a specific id = session is grade-locked and only shows to students of that exact grade (see /student/sessions/today).
// CASE (update-1, days vs day_of_week): sending "days" creates one row per day and returns an array in `data`; sending only "day_of_week" (legacy) returns a single object in `data`, unchanged.

{
  "teacher_id": 1,
  "subject_id": 1,
  "course_id": 1,
  "days": ["Saturday", "Monday", "Wednesday"],
  "start_time": "string",
  "end_time": "string",
  "room": "string",
  "is_online": 0,
  "meeting_link": "string",
  "grade": "string",
  "academic_year_id": 1
}

// CASE (decision=rejected): only id/decision/admin_note matter, everything else below is ignored.
// CASE (decision=approved, 3 sub-scenarios):
// 1) Default (no keep_original_schedule, no new_day/time overrides) -> applies the teacher's own originally-requested new_day/new_start_time/new_end_time as-is.
// 2) new_day/new_start_time/new_end_time sent -> OVERRIDES the teacher's requested time with the admin's own choice instead.
// 3) keep_original_schedule=true -> ignores any new day/time entirely, keeps the session at its CURRENT day/time, and instead REASSIGNS it to new_teacher_id (which becomes REQUIRED in this case and is validated against that teacher's course/subject+grade assignment).

{
  "id": 1,
  "decision": "approved",
  "admin_note": "string",
  "keep_original_schedule": true,
  "new_teacher_id": 1,
  "new_day": "string",
  "new_start_time": "string",
  "new_end_time": "string"
}

// CASE (3 scenarios, decided by which of course_id/unit_id/subject_id you send):
// 1) course_id ONLY -> exam applies to the WHOLE course (all units) — unit_id must be omitted/null.
// 2) course_id + unit_id -> exam is scoped to that ONE unit inside the course only — students only see it while inside that unit.
// 3) course_id + subject_id (course spans multiple subjects) -> further narrows the whole-course exam to just that subject's students.
// subject_id and unit_id can be combined with course_id independently; there is no exam scoped by subject_id alone without a course_id.

{
  "course_id": 1,
  "unit_id": 1,
  "subject_id": 1,
  "duration_minutes": 30,
  "total_marks": 100,
  "pass_marks": 50,
  "is_active": 1,
  "title_ar": "string",
  "title_en": "string",
  "title": "string",
  "description_ar": "string",
  "description_en": "string",
  "description": "string"
}

// CASE 1 (scope resolution): course_id/unit_id/subject_id are OPTIONAL — if omitted, the server auto-resolves them from exam_id (inherits whatever course/unit/subject the parent exam itself belongs to, see /admin/exams cases above). Only send them explicitly to override; if the course can't be resolved at all (bad exam_id), the request fails with 422.
// CASE 2 (question_type decides which answer-fields are used, others are ignored/must be omitted):
// - question_type=mcq -> use mcq_options[] (each option has is_correct); correct_answer and model_answer_* are ignored.
// - question_type=true_false -> use correct_answer (0 or 1); mcq_options and model_answer_* are ignored.
// - question_type=written -> use model_answer_ar/model_answer_en/model_answer (for reference/manual grading); mcq_options and correct_answer are ignored, this type is NOT auto-graded.

{
  "exam_id": 1,
  "course_id": 1,
  "unit_id": 1,
  "subject_id": 1,
  "question_type": "mcq",
  "order_num": 1,
  "score": 1,
  "is_active": 0,
  "question_text_ar": "string",
  "question_text_en": "string",
  "question_text": "string",
  "mcq_options": [
    {
      "option_key": "string",
      "is_correct": true,
      "option_image": "string",
      "option_text_ar": "string",
      "option_text_en": "string",
      "option_text": "string"
    }
  ],
  "correct_answer": 0,
  "model_answer_ar": "string",
  "model_answer_en": "string",
  "model_answer": "string"
}

// CASE (per answer item, only ONE of the 3 answer fields applies, matching that question's question_type): mcq_option_id for question_type=mcq (auto-graded); true_false_answer (0/1) for question_type=true_false (auto-graded); written_answer_text for question_type=written (NOT auto-graded — needs a teacher to grade it via /teacher/exams/attempts before the attempt's overall status becomes 'graded').
// CASE (auto report side effect): if the attempt has ZERO written questions, grading completes immediately in this same request and auto_generate_exam_result_report fires right away; if it has ANY written question, status stays pending and the report only gets auto-generated later once a teacher grades the written answers.

{
  "attempt_id": 1,
  "answers": [
    {
      "question_id": 1,
      "mcq_option_id": 1,
      "true_false_answer": 0,
      "written_answer_text": "string"
    }
  ]
}

// CASE (is_completed=1): fires an internal course-progress check on EVERY such call, but only actually writes a student_reports row (report_type=academic_performance, one-time) on whichever specific call happens to push the student's overall course progress to exactly 100% — earlier completions in the same course write no report. CASE (is_completed=0 or omitted): no side effect, just updates watch position.

{
  "video_id": 1,
  "watched_seconds": 1,
  "total_seconds": 1,
  "last_position_seconds": 1,
  "is_completed": 0
}

// update-1: validates the code only, does not create the student or consume the code yet

{
  "code": "ABCD1234"
}

// update-1: same body as normal /student/register, code itself comes from the onboarding_token, not from this body

{
  "name": "Ahmed Ali",
  "email": "ahmed@example.com",
  "password": "secret123",
  "phone": "01000000000",
  "academic_year_id": 1,
  "city_id": 1,
  "study_language": "arabic"
}

// update-1: code must already be claimed by a student (claimed_by_student_id set) — otherwise error

{
  "code": "ABCD1234"
}

// update-1: no student_id in body — the linked student comes from the onboarding_token issued by /parent/onboard/start

{
  "name": "Mona Ali",
  "email": "mona@example.com",
  "password": "secret123",
  "city_id": 1
}

// update-1: CASE course: send course_ids only. CASE subject: send subject_ids only (auto-expands to that subject’s courses, grade-scoped). CASE teacher: send teacher_ids only (auto-expands to everything that teacher teaches, grade-scoped). Sending a mix of two or more of these creates subscription_type=custom.

{
  "student_id": 10,
  "subject_ids": [
    3
  ],
  "duration_days": 30
}

// update-1: CASE course code: course_ids only, NOT grade-limited (gives access to exactly those courses regardless of student grade). CASE subject/teacher code: subject_ids or teacher_ids only, grade-scoped on redemption exactly like direct grant.

{
  "title": "Full course access - Math",
  "course_ids": [
    5,
    6
  ],
  "max_uses": 50,
  "duration_days": 90
}

// update-1: switching this code from subject-type to teacher-type: subject_ids sent empty to clear the old targets, teacher_ids sent with the new target

{
  "id": 12,
  "subject_ids": [],
  "teacher_ids": [
    7
  ],
  "course_ids": []
}

// update-1: claimed_by_student_id gets set on this student the first time this code is redeemed by anyone

{
  "code": "ABCD1234"
}

// CASE all=true: marks every unread notification as read. CASE notification_id set: marks just that one.

{
  "all": true
}

// creates one slot every Saturday and every Thursday at 18:00 from today through 2026-10-15

{
  "days": [
    "Saturday",
    "Thursday"
  ],
  "slot_time": "18:00",
  "end_date": "2026-10-15",
  "subject_id": 3,
  "meeting_type": "video_call",
  "type": "educational",
  "notes": "Weekly review session"
}

// update-2: only `kind` is new here; sending it as "package" is the only thing that distinguishes this create call from a normal course create

{
  "name_ar": "باقة متابعة أسبوعية عامة",
  "price": 49.99,
  "kind": "package"
}

{
  "id": 229,
  "kind": "package"
}

{
  "subject_id": 3,
  "name_ar": "باقة متابعة أسبوعية",
  "price": 49.99,
  "kind": "package"
}
